<?php
function operating_expenses(): void {
    [$from,$to]=report_dates();$category=(string)($_GET['category']??'');$cats=['Utilities','Maintenance','Supplies','Salaries','Other'];if($category&&!in_array($category,$cats,true))throw new RuntimeException('Choose a valid expense category.');
    $params=[$from,$to];$where='x.expense_date BETWEEN ? AND ?';if($category){$where.=' AND x.category=?';$params[]=$category;}
    $all=rows('SELECT x.*,u.name FROM expenses x JOIN users u ON u.id=x.recorded_by WHERE '.$where.' ORDER BY expense_date DESC,x.id DESC',$params);$active=array_filter($all,fn($x)=>!$x['voided_at']);$total=array_sum(array_column($active,'amount'));
    echo '<div class="operation-summary"><div><span>Recorded operating costs</span><strong>'.money($total).'</strong></div><div><span>Active expense entries</span><strong>'.count($active).'</strong></div><div><span>Voided entries</span><strong>'.(count($all)-count($active)).'</strong></div></div>';
    section_start('Expense register','Filter recorded costs. Voided entries remain in history and are excluded from totals.');echo '<form method="get" class="report-filter"><input type="hidden" name="page" value="expenses">';field('From','from','date',$from);field('Through','to','date',$to);select_field('Category','category',[''=>'All categories']+array_combine($cats,$cats),$category);echo '<button class="primary">Apply filters</button><a class="button" href="?export=expenses&from='.e($from).'&to='.e($to).'">Export period CSV</a></form><div class="table-wrap"><table><thead><tr><th>Date / reference</th><th>Payee / description</th><th>Category / method</th><th>Amount</th><th>Recorded by</th><th>Status / action</th></tr></thead><tbody>';if(!$all)empty_row(6,'No expenses in this reporting period.');foreach($all as $x){echo '<tr class="'.($x['voided_at']?'voided-row':'').'"><td>'.e($x['expense_date']).'<small>'.e($x['reference']?:'No invoice reference').'</small></td><td><strong>'.e($x['vendor']?:'Payee not recorded').'</strong><small>'.e($x['description']).'</small></td><td>'.e($x['category']).'<small>'.e($x['payment_method']).'</small></td><td>'.money($x['amount']).'</td><td>'.e($x['name']).'</td><td>';if($x['voided_at'])echo badge('voided').'<small>'.e($x['void_reason']).'</small>';else{echo badge('recorded').'<details><summary>Void incorrect entry</summary>';form_start('void_expense','expenses');echo '<input type="hidden" name="expense_id" value="'.$x['id'].'">';field('Reason','reason');echo '<div class="form-actions"><button class="danger" data-confirm="Void this expense? It will remain in history and be excluded from financial totals.">Void expense</button></div></form></details>';}echo '</td></tr>';}echo '</tbody></table></div></section>';
    section_start('Record an operating expense','Use the supplier receipt or invoice. These costs do not change a tenant’s billing statement.');form_start('expense','expenses');echo '<input type="hidden" name="idempotency_key" value="'.bin2hex(random_bytes(16)).'">';field('Payee / supplier','vendor','text','',true,'maxlength="200"');select_field('Category','category',array_combine($cats,$cats));select_field('Paid through','payment_method',['Cash'=>'Cash','GCash'=>'GCash','Bank transfer'=>'Bank transfer']);field('Description / purpose','description','text','',true,'maxlength="255"');amount_field('Amount paid (PHP)','amount');field('Expense date','expense_date','date',date('Y-m-d'),true,'max="'.date('Y-m-d').'"');field('Invoice / transaction reference','reference','text','',false,'maxlength="150"');submit('Save expense');echo '</section>';
}
function assignment_panel(?int $tenantId=null,?int $bedId=null,string $return='tenants'): void {
    $beds=bed_options();$tenants=rows("SELECT t.* FROM tenants t WHERE t.status='active' AND NOT EXISTS(SELECT 1 FROM tenant_assignments a WHERE a.tenant_id=t.id AND a.end_date IS NULL) ORDER BY t.name");
    section_start('Assign a resident','Choose a registered resident, select an available bed, then confirm the move-in date.');
    if(!$beds||!$tenants) { echo '<p class="empty">'.(!$beds?'No beds are available in active rooms.':'All active residents already have a bed. New tenants can register on the login page.').'</p></section>'; return; }
    form_start('assign_tenant',$return);$options=[];foreach($tenants as $t)$options[$t['id']]=$t['name'].' · '.$t['email'];select_field('Resident awaiting assignment','tenant_id',$options,$tenantId??array_key_first($options));select_field('Available room / bed','bed_id',$beds,$bedId??array_key_first($beds));field('Move-in date','move_in','date',date('Y-m-d'),true,'max="'.date('Y-m-d').'"');echo '<p class="form-wide muted">Room rent applies to future statements. Assignment does not create a bill or record a payment.</p>';submit('Confirm room assignment');echo '</section>';
}
function resident_directory(): void {
    $all=rows('SELECT t.*,r.number,b.label,u.username FROM tenants t LEFT JOIN tenant_assignments a ON a.tenant_id=t.id AND a.end_date IS NULL LEFT JOIN bed_spaces b ON b.id=a.bed_id LEFT JOIN rooms r ON r.id=b.room_id LEFT JOIN users u ON u.tenant_id=t.id ORDER BY t.name');
    $selected=(int)($_GET['tenant_id']??0);$resident=null;foreach($all as $t)if((int)$t['id']===$selected)$resident=$t;
    $unassigned=count(array_filter($all,fn($t)=>$t['status']==='active'&&!$t['number']));
    echo '<div class="operation-summary"><div><span>Awaiting assignment</span><strong>'.$unassigned.'</strong></div><div><span>Assigned residents</span><strong>'.count(assigned()).'</strong></div><div><span>Available beds</span><strong>'.count(available_beds()).'</strong></div></div>';
    if(!$resident) { echo '<details class="panel" id="assign-resident"><summary>Assign room / bed</summary>'; assignment_panel(); echo '</details>'; }
    if($resident) {
        $t=$resident;section_start($t['name'],'Resident profile and accommodation');echo '<div class="resident-profile"><div><span class="eyebrow">CURRENT ACCOMMODATION</span><h3>'.($t['number']?'Room '.e($t['number']).' / '.e($t['label']):'Awaiting room assignment').'</h3>'.badge($t['status']).'<p>'.e($t['email']).'<br>'.e($t['contact']).'</p></div><a class="button" href="?page=tenants">Back to residents</a></div>';form_start('tenant_update','tenants');echo '<input type="hidden" name="tenant_id" value="'.$t['id'].'">';field('Full name','name','text',$t['name']);field('Email','email','email',$t['email']);field('Contact number','contact','tel',$t['contact']);submit('Save resident details');echo '</section>';
        if($t['status']==='active'&&!$t['number']) assignment_panel((int)$t['id']);
        if($t['status']==='active'&&$t['number']) { section_start('Change accommodation','A transfer retains the resident’s existing bills and assignment history.');$beds=bed_options();if($beds){form_start('transfer','tenants');echo '<input type="hidden" name="tenant_id" value="'.$t['id'].'">';select_field('New room / bed','bed_id',$beds);field('Transfer date','transfer_date','date',date('Y-m-d'),true,'max="'.date('Y-m-d').'"');submit('Confirm transfer');}echo '<details class="moveout-section"><summary>Record move-out</summary>';form_start('moveout','tenants');echo '<input type="hidden" name="tenant_id" value="'.$t['id'].'">';field('Move-out date','move_out','date',date('Y-m-d'));submit('Record move-out');echo '</details></section>'; }
        section_start('Accommodation history');foreach(rows('SELECT a.*,r.number,b.label FROM tenant_assignments a JOIN bed_spaces b ON b.id=a.bed_id JOIN rooms r ON r.id=b.room_id WHERE tenant_id=? ORDER BY a.id DESC',[$t['id']]) as $a)echo '<div class="history-row"><strong>Room '.e($a['number']).' / '.e($a['label']).'</strong><span>'.e($a['start_date']).' — '.e($a['end_date']??'Current').'</span></div>';echo '<p>Account: '.($t['username']?e($t['username']):'<a href="?page=tenants#existing-tenant-account">Create resident login</a>').'</p></section>';
    }
    $balances=[];$states=[];
    foreach(aging_rows() as $b) { $id=$b['tenant_id'];$balances[$id]=($balances[$id]??0)+balance($b);$state=status($b);if(!isset($states[$id])||$state==='overdue'||($state==='partial'&&$states[$id]!=='overdue')||($state==='unpaid'&&$states[$id]==='paid'))$states[$id]=$state; }
    section_start('Resident directory','Manage accommodation and open each resident account history. Balances include confirmed payments only.');
    echo '<div class="directory-toolbar"><input class="table-search" data-search="tenant-table" placeholder="Search name, room, or contact" aria-label="Search residents"><a class="button primary" href="#add-resident">Add Resident</a></div><div class="table-wrap"><table id="tenant-table"><thead><tr><th>Resident / contact</th><th>Room &amp; bed</th><th>Move-in date</th><th>Status</th><th>Current balance</th><th>Payment status</th><th>Actions</th></tr></thead><tbody>';
    if(!$all)empty_row(7);
    foreach($all as $t)echo '<tr><td><strong>'.e($t['name']).'</strong><small>'.e($t['contact']).'</small><small>'.e($t['email']).'</small></td><td>'.($t['number']?'Room '.e($t['number']).' / '.e($t['label']):'<span class="assignment-waiting">Awaiting assignment</span>').'</td><td>'.e($t['move_in']?:'Not moved in').'</td><td>'.badge($t['status']).'</td><td>'.money($balances[$t['id']]??0).'</td><td>'.(isset($states[$t['id']])?badge($states[$t['id']]):'No statement').'</td><td><div class="resident-actions"><a href="?page=tenants&tenant_id='.$t['id'].'">View / Edit</a>'.($t['status']==='active'?'<a href="?page=tenants&tenant_id='.$t['id'].'">'.($t['number']?'Transfer bed':'Assign room').'</a>':'').'<a href="?page=ledger&tenant_id='.$t['id'].'">Billing History</a></div></td></tr>';
    echo '</tbody></table></div></section><details class="panel" id="add-resident"><summary>Add Resident</summary>';tenant_registration_form('tenants');echo '</details><details class="panel" id="existing-tenant-account"><summary>Create login for an existing resident</summary>';existing_resident_login();echo '</details>';

}
function room_inventory(): void {
    $bedId=(int)($_GET['bed_id']??0);
    if($bedId){$bed=one('SELECT b.*,r.number,r.rent,r.status,t.name,t.id tenant_id FROM bed_spaces b JOIN rooms r ON r.id=b.room_id LEFT JOIN tenant_assignments a ON a.bed_id=b.id AND a.end_date IS NULL LEFT JOIN tenants t ON t.id=a.tenant_id WHERE b.id=?',[$bedId]);if($bed){echo '<section class="panel bed-selection"><span class="eyebrow">SELECTED BED</span><h2>Room '.e($bed['number']).' / '.e($bed['label']).'</h2><p>'.money($bed['rent']).' monthly rent</p>';if($bed['tenant_id'])echo '<p>Occupied by <strong>'.e($bed['name']).'</strong></p><a class="button" href="?page=tenants&tenant_id='.$bed['tenant_id'].'">Open resident / transfer</a>';elseif($bed['status']!=='active')echo '<div class="notice">This room is under maintenance. Assignment is unavailable.</div>';echo '</section>';if(!$bed['tenant_id']&&$bed['status']==='active')assignment_panel(null,$bedId,'rooms');}}
    echo '<div class="room-grid">';foreach(rows('SELECT * FROM rooms ORDER BY number') as $r){$beds=rows('SELECT b.*,t.name FROM bed_spaces b LEFT JOIN tenant_assignments a ON a.bed_id=b.id AND a.end_date IS NULL LEFT JOIN tenants t ON t.id=a.tenant_id WHERE b.room_id=? ORDER BY b.id',[$r['id']]);$occupied=count(array_filter($beds,fn($b)=>$b['name']!==null));echo '<section class="panel room-card"><div class="panel-heading"><div><h2>Room '.e($r['number']).'</h2><p class="muted">'.money($r['rent']).' per bed / month &middot; '.($r['capacity']==1?'Single room':'Shared room').'</p></div>'.badge($r['status']).'</div><div class="bed-grid">';foreach($beds as $b)echo '<a href="?page=rooms&bed_id='.$b['id'].'" class="bed bed-link '.($b['name']?'occupied':'available').'" aria-label="'.e($b['label'].': '.($b['name']??'Available')).'"><span>▰</span><strong>'.e($b['label']).'</strong><small>'.e($b['name']??($r['status']==='active'?'Assign resident':'Maintenance')).'</small></a>';echo '</div><div class="room-capacity"><strong>'.$occupied.' / '.$r['capacity'].' occupied</strong><span>'.($r['capacity']-$occupied).' unassigned</span></div><details><summary>Room settings</summary>';form_start('room_update','rooms');echo '<input type="hidden" name="room_id" value="'.$r['id'].'">';amount_field('Monthly rent per bed','rent',$r['rent']/100);select_field('Status','status',['active'=>'Active','maintenance'=>'Maintenance'],$r['status']);submit('Save room settings');echo '</details></section>';}echo '</div><details class="panel"><summary>Add a room</summary>';form_start('room','rooms');field('Room number','number');field('Bed capacity','capacity','number',4,true,'min="1" max="30"');amount_field('Monthly rent per bed','rent',5000);submit('Create room');echo '</details>';
}
function document_header(string $title,string $reference,string $date): void {
    echo '<header class="document-header"><div><div class="document-brand">A</div><h2>'.e(setting('business_name','Angelina’s Dormitory')).'</h2><p>'.e(setting('business_address')?:'Dormitory administration office').'<br>'.e(setting('business_contact')).'</p></div><div class="document-number"><span>'.e($title).'</span><strong>'.e($reference).'</strong><small>'.e($date).'</small></div></header>';
}
function professional_statement(array $u): void {
    $b=bill((int)($_GET['id']??0));if(!$b||($u['role']==='tenant'&&(int)$b['tenant_id']!==(int)$u['tenant_id'])){http_response_code(404);echo '<div class="notice error">Statement not found.</div>';return;}
    $a=one('SELECT r.number,bs.label FROM tenant_assignments a JOIN bed_spaces bs ON bs.id=a.bed_id JOIN rooms r ON r.id=bs.room_id WHERE a.id=?',[$b['assignment_id']]);$ref='AD-B'.str_pad((string)$b['id'],5,'0',STR_PAD_LEFT);
    echo '<div class="document-toolbar no-print"><a class="button" href="?page=billing">Back to statements</a><button type="button" class="primary" data-print>Print / save PDF</button></div><section class="panel printable business-document">';document_header('STATEMENT OF ACCOUNT',$ref,'Billing period: '.$b['period']);echo '<div class="document-parties"><div><span>BILLED TO</span><strong>'.e($b['name']).'</strong><p>'.e($b['email']).'<br>Room '.e($a['number']).' · '.e($a['label']).'</p></div><div><span>PAYMENT SCHEDULE</span><p>Cutoff: <strong>'.e($b['cutoff']).'</strong><br>Due date: <strong>'.e($b['due_date']).'</strong></p>'.badge(status($b)).'</div></div><table class="document-table"><thead><tr><th>Description</th><th>Amount (PHP)</th></tr></thead><tbody>';
    foreach(['rent'=>'Monthly bed rental','electricity'=>'Electricity charge','water'=>'Water charge','previous_balance'=>'Balance brought forward'] as $key=>$label)echo '<tr><td>'.e($label).'</td><td>'.money($b[$key]).'</td></tr>';foreach(rows('SELECT * FROM billing_adjustments WHERE billing_id=? ORDER BY id',[$b['id']]) as $adj)echo '<tr><td>'.e(ucfirst($adj['type'])).'<small>'.e($adj['reason']).'</small></td><td>'.($adj['type']==='discount'?'−':'').money($adj['amount']).'</td></tr>';echo '</tbody></table><div class="document-totals"><p><span>Total charges and carried balance</span><strong>'.money($b['total_due']).'</strong></p><p><span>Confirmed payments</span><strong>'.money($b['paid']).'</strong></p><p class="amount-due"><span>Remaining balance</span><strong>'.money(balance($b)).'</strong></p></div>';
    if($b['carried_to'])echo '<p class="document-note">This balance was carried to statement #'.$b['carried_to'].'. Payment must be applied to the current statement.</p>';
    $payments=rows('SELECT * FROM payments WHERE billing_id=? AND voided_at IS NULL ORDER BY payment_date,id',[$b['id']]);if($payments){echo '<h3 class="document-section-title">Payments applied</h3><table class="document-table"><thead><tr><th>Date / receipt</th><th>Method</th><th>Amount</th></tr></thead><tbody>';foreach($payments as $p)echo '<tr><td>'.e($p['payment_date']).' · AD-'.str_pad((string)$p['id'],6,'0',STR_PAD_LEFT).'</td><td>'.e($p['method']).'</td><td>'.money($p['amount']).'</td></tr>';echo '</tbody></table>';}
    echo '<div class="document-note"><strong>Payment terms</strong><p>Please settle the current balance by the due date. Partial payments are applied after verification. Security deposits are tracked separately. This statement is a billing record, not a payment receipt.</p></div><footer class="document-footer"><span>Prepared by dormitory administration</span><span>'.$ref.' · Generated '.date('M j, Y').'</span></footer></section>';if($u['role']==='tenant'&&!$b['carried_to']&&balance($b)>0)echo '<a class="button primary no-print" href="?page=pay&bill_id='.$b['id'].'">Make a payment</a>';
    if($u['role']==='admin'&&!$b['carried_to']){echo '<div class="no-print">';section_start('Statement correction','Corrections require a reason and remain in the audit history.');form_start('adjust_bill','billing');echo '<input type="hidden" name="billing_id" value="'.$b['id'].'">';select_field('Correction type','type',['adjustment'=>'Adjustment','discount'=>'Discount']);amount_field('Amount','amount',0,true);field('Reason','reason');submit('Apply correction');echo '</section></div>';}
}
function professional_receipt(array $u): void {
    $p=one('SELECT p.*,t.name,b.period,r.number,bs.label,u.name receiver FROM payments p JOIN tenants t ON t.id=p.tenant_id JOIN billing b ON b.id=p.billing_id JOIN tenant_assignments a ON a.id=b.assignment_id JOIN bed_spaces bs ON bs.id=a.bed_id JOIN rooms r ON r.id=bs.room_id JOIN users u ON u.id=p.received_by WHERE p.id=?',[(int)($_GET['id']??0)]);if(!$p||($u['role']==='tenant'&&(int)$p['tenant_id']!==(int)$u['tenant_id'])){http_response_code(404);echo '<div class="notice error">Receipt not found.</div>';return;}$b=bill((int)$p['billing_id']);$ref='AD-'.str_pad((string)$p['id'],6,'0',STR_PAD_LEFT);
    echo '<div class="document-toolbar no-print"><a class="button" href="?page=payments">Back to payments</a><button class="primary" type="button" data-print>Print / save PDF</button></div><section class="panel printable business-document receipt-document">';document_header('PAYMENT RECEIPT',$ref,'Payment date: '.$p['payment_date']);echo '<div class="document-parties"><div><span>RECEIVED FROM</span><strong>'.e($p['payer']).'</strong><p>Resident: '.e($p['name']).'<br>Room '.e($p['number']).' · '.e($p['label']).'</p></div><div><span>Payment confirmation</span>'.badge($p['voided_at']?'voided':'paid').'<p>Billing period: '.e($p['period']).'<br>Statement: AD-B'.str_pad((string)$p['billing_id'],5,'0',STR_PAD_LEFT).'</p></div></div><div class="receipt-amount"><span>AMOUNT RECEIVED</span><strong>'.money($p['amount']).'</strong></div><table class="document-table"><tbody>';foreach(['Payment method'=>$p['method'],'Transaction reference'=>$p['reference']?:'Office payment','Received / verified by'=>$p['receiver'],'Applied to'=>'Rent and utilities · '.$p['period'],'Balance when payment was received'=>$p['balance_after']!==null?money($p['balance_after']):'Historical snapshot unavailable','Current statement balance'=>money(balance($b))] as $label=>$value)echo '<tr><td>'.e($label).'</td><td>'.e($value).'</td></tr>';echo '</tbody></table><p class="document-note">The current statement balance can change after later payments or corrections. The balance at receipt time is preserved.</p>';if($p['voided_at'])echo '<div class="document-void">VOIDED — '.e($p['void_reason']).'<br>'.e($p['voided_at']).' UTC. This payment is excluded from collections.</div>';echo '<footer class="document-footer"><span>System-generated dormitory payment acknowledgement</span><span>'.$ref.'</span></footer></section><a class="button no-print" href="?page=statement&id='.$p['billing_id'].'">View billing statement</a>';
    if($u['role']==='admin'&&!$p['voided_at']&&!$b['carried_to']){echo '<div class="no-print">';section_start('Correct payment','Voiding preserves this receipt and restores the statement balance.');form_start('void_payment','payments');echo '<input type="hidden" name="payment_id" value="'.$p['id'].'">';field('Reason','reason');echo '<div class="form-actions"><button class="danger" data-confirm="Void this payment?">Void payment</button></div></form></section></div>';}
}
